// demo-30.ts：goal——长期目标持久化与跨会话目标追踪（真实实现）
// 本实验直接使用 dsh 真实包：
//   - @deepseek-ai/dsh-goal     GoalService：ctx.goals（create/edit/pause/resume/complete 真实状态机）
//   - @deepseek-ai/dsh-session + dsh-session-projection + dsh-agent  底座（live agent 注册、投影）
// 全链路真实：目标创建、编辑、暂停、恢复、完成、goal/change 事件与 goal 投影全部走真实机制。
import { Context } from '@deepseek-ai/cordis'
import { SessionStore } from '@deepseek-ai/dsh-session'
import { SessionProjectionRegistry } from '@deepseek-ai/dsh-session-projection'
import AgentRegistry from '@deepseek-ai/dsh-agent'
import GoalService from '@deepseek-ai/dsh-goal'

async function main() {
  console.log('=== goal：长期目标持久化与跨会话目标追踪（真实实现）===\n')
  const root = new Context()
  await root.plugin(SessionStore)
  await root.plugin(SessionProjectionRegistry)
  await root.plugin(AgentRegistry as any, {})
  await root.plugin(GoalService as any, {})
  const session = root.sessions.create('goal-demo', { meta: { cwd: process.cwd() } })
  const agent = { id: session.id, session, ctx: root } as unknown as any
  ;(root as any).agents.register(agent)
  const goals = (root as any).goals
  console.log('  → ctx.goals 就绪（真实 GoalService）')

  // ========== 1. 创建目标 ==========
  console.log('\n--- 1. 创建目标（create，真实状态机：phase=active + armed）---')
  const created: any = goals.create(agent, { objective: '完成 DeepSeek Harness 60 篇系列', maxGoalRounds: 10 })
  console.log(`  → id=${created.id}`)
  console.log(`  → phase=${created.phase}, revision=${created.revision}, maxGoalRounds=${created.maxGoalRounds}`)
  console.log(`  → activation=${created.activation}`)

  // ========== 2. 编辑目标 ==========
  console.log('\n--- 2. 编辑目标（edit，revision 递增）---')
  const ref1 = { id: created.id, revision: created.revision }
  const edited: any = goals.edit(agent, ref1, { objective: '完成 DeepSeek Harness 60 篇系列并全部真实化' })
  console.log(`  → objective=${edited.objective}`)
  console.log(`  → revision=${edited.revision}（+1）`)

  // ========== 3. 暂停 / 恢复 ==========
  console.log('\n--- 3. 暂停 / 恢复（pause → phase=paused；resume → phase=active+armed）---')
  const paused: any = goals.pause(agent, { id: edited.id, revision: edited.revision })
  console.log(`  → pause 后 phase=${paused.phase}, activation=${paused.activation}`)
  const resumed: any = goals.resume(agent, { id: paused.id, revision: paused.revision })
  console.log(`  → resume 后 phase=${resumed.phase}, activation=${resumed.activation}`)

  // ========== 4. 完成 ==========
  console.log('\n--- 4. 完成（complete → phase=complete + disarmed）---')
  const done: any = goals.complete(agent, { id: resumed.id, revision: resumed.revision })
  console.log(`  → complete 后 phase=${done.phase}, activation=${done.activation}`)

  // ========== 5. 投影（跨会话可读） ==========
  console.log('\n--- 5. goal 投影（sessionProjections，跨会话可追踪）---')
  const proj = (root as any).sessionProjections.snapshot(session, ['goal'])
  console.log(`  → 投影 values.goal = ${JSON.stringify(proj.values.goal).slice(0, 200)}`)
  const evt = session.snapshotEvents().filter((e: any) => e.type === 'goal/change')
  console.log(`  → goal/change 事件帧 ${evt.length} 条（审计留痕：谁在何时改了目标）`)

  // ========== 6. 重复创建被拒（真实约束） ==========
  console.log('\n--- 6. 已完成目标可替换；活跃目标重复创建被拒（真实约束）---')
  const again: any = goals.create(agent, { objective: '新目标：发布线上版本', maxGoalRounds: 5 })
  console.log(`  → 替换完成目标：新 id=${again.id}（允许）`)
  try {
    goals.create(agent, { objective: '又建一个', maxGoalRounds: 5 })
    console.log('  → ?? 未报错（不应该）')
  } catch (e: any) {
    console.log(`  → 重复创建被拒：${(e?.message ?? String(e)).slice(0, 80)}（GOAL_ALREADY_EXISTS 真实机制）`)
  }

  console.log('\n=== 实验完成 ===')
  await (root as any).fiber.dispose()
}

main().catch((err) => { console.error(err); process.exit(1) })
